    vocab:[["BREAKFAST","the first meal of the day"],["NUNS","religious women who live and work together"],["DONATED","gave money or things to help others"],["RECORD","a round disc that plays music"],["MUSEUM","a building where interesting old objects are shown"],["CHANGES","becomes different"],["CONVENTIONAL","following usual, ordinary ideas and behavior"],["SKATING","moving on ice wearing special boots with blades"],["SUGGESTED","put forward an idea"],["INSULTED","said something rude and unkind to someone"],["ANGRY","feeling strong displeasure"],["CRIED","produced tears"]],
    comp:[["Who does Holden have breakfast with?",["Phoebe","Two nuns","Sally Hayes","Jane Gallagher"],1,"He has breakfast with two nuns."],["What does Holden do before the nuns leave?",["He argues with them","He donates money to their charity","He asks for advice","He invites them to lunch"],1,"He donates money to their charity."],["What does Holden buy for Phoebe?",["A book","A record","A hat","A bicycle"],1,"He buys her a record."],["What does Holden love about the museum?",["The food there","That nothing ever changes inside it","The loud crowds","The modern art"],1,"He loves that nothing ever changes there."],["Who is Sally Hayes?",["Holden's sister","A pretty, conventional girl he dates","A nun","A jazz singer"],1,"She is a pretty, conventional girl he dates."],["What do Holden and Sally do that afternoon?",["Play checkers","See a play and go ice skating","Visit the museum","Go to Ernie's"],1,"They see a play and go ice skating."],["What does Holden suggest to Sally?",["Getting married in New York","Running away to live in the countryside","Going back to Pencey","Meeting Jane"],1,"He suggests running away together."],["How does the date end?",["Happily","Badly, after Holden insults Sally","With a kiss","With a plan for Vermont"],1,"It ends badly, after he insults her."]],
