  { n:6, title:"The Wicker Bar and the ducks", unit:6, span:"Chapters 18–20",
    sum:"Holden watches a film at Radio City that he despises, then drinks with Carl Luce, an older former schoolmate, who advises him to see a psychoanalyst. Very drunk, Holden calls Sally at midnight and then goes to Central Park to find the ducks. There he drops and breaks Phoebe's record, and imagines his own funeral and Allie's grave in the rain.",
    vocab:[["FILM","a story shown as moving pictures"],["DESPISED","disliked something very strongly"],["DRINKS","alcoholic beverages"],["SCHOOLMATE","someone who was at school with you"],["THERAPIST","a person who helps people talk about and understand their problems"],["DRUNK","affected by too much alcohol"],["MIDNIGHT","twelve o'clock at night"],["CENTRAL","in or near the middle of a place"],["BROKE","damaged something so it no longer works"],["FUNERAL","a ceremony held after someone dies"],["GRAVE","the place in the ground where a dead person is buried"],["RAIN","water falling from clouds"]],
    comp:[["How does Holden feel about the film at Radio City?",["He loves it","He despises it","He falls asleep","He does not watch it"],1,"He despises the film."],["Who is Carl Luce?",["Holden's brother","An older former schoolmate","A taxi driver","A hotel worker"],1,"He is an older former schoolmate."],["What does Carl Luce suggest Holden should do?",["Go home","See a therapist","Call Jane","Return to Pencey"],1,"He suggests seeing a therapist."],["Who does Holden call at midnight?",["Phoebe","Sally Hayes","Jane Gallagher","Mr. Antolini"],1,"He calls Sally Hayes."],["Where does Holden go after the phone call?",["Back to the hotel","Central Park, to find the ducks","Ernie's","The museum"],1,"He goes to Central Park."],["What happens to Phoebe's record?",["Holden gives it away","It breaks","He loses it on the train","Phoebe breaks it"],1,"It breaks in the park."],["What does Holden imagine while sitting in the rain?",["His own funeral","A film he wants to make","Winning a football game","Talking to Mr. Spencer"],0,"He imagines his own funeral."],["Whose grave does Holden also picture?",["Mr. Spencer's","Allie's","Jane's father's","His own"],1,"He pictures Allie's grave."]],
    tf:[["Holden really enjoys the film at Radio City.",false,"He despises it."],["Carl Luce suggests Holden see a therapist.",true,"This is correct."],["Holden calls Sally Hayes at midnight.",true,"This is correct."],["Holden easily finds the ducks in Central Park.",false,"He cannot find any ducks."],["Phoebe's record breaks in the park.",true,"This is correct."],["Holden feels completely calm sitting in the rain.",false,"He feels overwhelmed with sadness."]],
    rw:[["Holden despised the film at Radio City.",0,"Right — this is correct."],["Carl Luce enjoyed Holden's endless questions.",1,"Wrong — he found them tiring and left early."],["Holden was completely sober when he called Sally.",1,"Wrong — he was very drunk."],["Holden found many ducks in Central Park.",1,"Wrong — he could not find any."],["Phoebe's record broke into pieces.",0,"Right — this is correct."],["Holden threw away the broken pieces of the record.",1,"Wrong — he carefully kept them."],["It was raining while Holden sat on the bench.",0,"Right — this is correct."],["Carl Luce paid for all the drinks that night.",2,"Doesn't say — the text does not say who paid."]],
    halves:[["Holden despises the film","he watches at Radio City."],["Carl Luce suggests","that Holden see a therapist."],["Very drunk, Holden calls","Sally Hayes at midnight."],["Holden goes to Central Park","to look for the ducks."],["Phoebe's record breaks","as Holden looks for the pond."],["Holden sits alone","on a bench in the rain."],["He imagines his own funeral","and pictures Allie's grave."]],
    odd:[[["film","play","drinks","show"],2,"Drinks is not a form of entertainment shown to an audience."],[["drunk","sober","tipsy","tired"],1,"Sober means the opposite of the others."],[["funeral","grave","cemetery","park"],3,"A park is not connected specifically to death."],[["broke","damaged","fixed","cracked"],2,"Fixed means the opposite of the others."],[["midnight","evening","night","morning"],3,"Morning is a different part of the day from the others."]],
    gaps:{title:"Prepositions", bank:["at","with","for","into","on","in"], items:[["Holden watched a film ___ Radio City.","at"],["He had drinks ___ Carl Luce.","with"],["He looked ___ the ducks in the park.","for"],["The record broke ___ small pieces.","into"],["Holden sat alone ___ a bench.","on"],["He pictured Allie's grave ___ the rain.","in"]]},
    think:{quote:"Sitting alone in the rain, Holden pictures his own funeral, and then Allie's grave, cold and wet under the same rain that is falling on him now.", question:"Why might Holden imagine his own funeral after such a difficult night?", options:["Because he plans to hurt himself","Because he feels overwhelmed by loneliness and loss, and it shows in his dark thoughts","Because Phoebe asked him to think about it"], answer:1, note:"Holden is not planning anything; the dark, sad images show how much pain and loneliness he is carrying that night."},
    writing:[{task:"Describe Holden's phone call to Sally Hayes at midnight.",target:"30-50 words",tips:["Say how Holden was feeling","Say what he said","Say how Sally reacted"],starters:["At midnight, Holden called...","He had been drinking, so...","Sally seemed...","The call ended..."]},{task:"Imagine you are Holden, sitting on the bench in the rain.",target:"30-50 words",tips:["Say what just happened to the record","Say what you imagine about your funeral","Say how you feel"],starters:["Phoebe's record just broke, and I...","Sitting here, I imagined...","I also thought about Allie's grave...","I felt..."]}]},
  { n:7, title:"Phoebe and Mr Antolini", unit:7, span:"Chapters 21–23",
    sum:"Holden sneaks into his family's apartment at night and wakes his clever, affectionate ten-year-old sister, Phoebe. She realizes he has been expelled again and challenges him, saying he doesn't like anything. Holden tells her he would like to be someone who catches children before they run off the edge of a cliff in a field of rye, and gives her his hunting hat before slipping out to spend the night at his old teacher Mr. Antolini's home, who warns him he is heading for a terrible fall. Holden wakes to find Antolini stroking his hair, panics, and leaves.",
    vocab:[["SNEAKED","moved quietly and secretly"],["APARTMENT","a set of rooms where a family lives"],["AFFECTIONATE","showing love and warmth"],["REALIZED","understood something suddenly"],["CHALLENGED","questioned someone strongly"],["CLIFF","a high, steep rock, often near the sea"],["CATCH","to take hold of something moving through the air"],["FIELD","an open area of land, often used for growing crops"],["WARNED","told someone about a possible danger"],["PANICKED","suddenly felt very frightened"],["STROKING","touching gently and repeatedly"],["SLIPPED","moved quietly and smoothly out"]],
    comp:[["How does Holden get into the family apartment?",["He rings the doorbell","He sneaks in quietly at night","He calls Phoebe first","He waits outside"],1,"He sneaks in quietly."],["How old is Phoebe?",["Eight","Ten","Twelve","Fourteen"],1,"She is ten years old."],["What does Phoebe quickly realize about Holden?",["That he is sick","That he has been expelled again","That he ran away from home before","That he is hungry"],1,"She realizes he has been expelled again."],["What does Phoebe challenge Holden to name?",["A job he wants","Something he truly likes","A place he wants to visit","A person he trusts"],1,"She challenges him to name something he likes."],["What does Holden say he would like to be?",["A teacher","Someone who catches children in a field of rye","A pilot","A jazz musician"],1,"He wants to catch children in a field of rye."],["What does Holden give Phoebe before he leaves?",["His jacket","His red hunting hat","Money","A record"],1,"He gives her his red hunting hat."],["What does Mr. Antolini warn Holden about?",["Bad grades","Heading toward a terrible fall","Losing Phoebe's trust","Missing his train"],1,"He warns him about a terrible fall."],["Why does Holden suddenly leave Mr. Antolini's apartment?",["He feels sick","He panics after waking up to Antolini stroking his hair","Antolini asks him to leave","He remembers an appointment"],1,"He panics and leaves quickly."]],
    tf:[["Holden enters the apartment quietly at night.",true,"This is correct."],["Phoebe is happy that Holden has been expelled again.",false,"She is not happy about this."],["Phoebe thinks Holden likes everything completely.",false,"She says he likes nothing."],["Holden gives Phoebe his hunting hat.",true,"This is correct."],["Mr. Antolini warns Holden kindly about his future.",true,"This is correct."],["Holden calmly falls back asleep at Mr. Antolini's apartment.",false,"He panics and leaves instead."]],
    rw:[["Holden sneaked into the apartment carefully.",0,"Right — this is correct."],["Phoebe realized Holden had been expelled again.",0,"Right — she noticed small details."],["Phoebe thought Holden liked many things completely.",1,"Wrong — she said he liked nothing."],["Holden gave Phoebe his red hunting hat.",0,"Right — this is correct."],["Mr. Antolini shouted angrily at Holden all night.",1,"Wrong — he spoke seriously but kindly."],["Holden's parents woke up while he was there.",2,"Doesn't say — the text does not say this."],["Holden panicked and left Mr. Antolini's apartment quickly.",0,"Right — this is correct."]],
    halves:[["Holden sneaks into","the family apartment at night."],["Phoebe quickly realizes","that Holden has been expelled again."],["Phoebe challenges Holden","to name something he truly likes."],["Holden imagines catching children","before they fall off a cliff in a field of rye."],["Before leaving, Holden gives Phoebe","his red hunting hat."],["Mr. Antolini warns Holden","that he is heading for a terrible fall."],["Holden panics and leaves","after waking up to Antolini stroking his hair."]],
    odd:[[["apartment","house","home","field"],3,"A field is outdoors, unlike the others."],[["affectionate","warm","loving","cold"],3,"Cold means the opposite of the others."],[["realized","understood","noticed","ignored"],3,"Ignored means the opposite of the others."],[["cliff","rock","edge","hat"],3,"A hat is clothing, unlike the others."],[["panicked","frightened","calm","scared"],2,"Calm means the opposite of the others."]],
    gaps:{title:"Question words", bank:["what","who","when","where","how","why"], items:[["___ did Holden give Phoebe before he left?","what"],["___ warned Holden about a terrible fall?","who"],["___ did Holden sneak into the apartment?","when"],["___ did Holden spend the night after seeing Phoebe?","where"],["___ did Phoebe react when she recognized the truth?","how"],["___ did Mr. Antolini invite Holden to stay?","why"]]},
    think:{quote:"Holden tells Phoebe that the only thing he would truly like to be is someone standing in a huge field of rye, catching children gently before they run over the edge of a cliff.", question:"Why do you think Holden imagines this particular job for himself?", options:["Because he actually wants to work outdoors","Because he wants to protect innocent children from danger and from growing up too fast","Because Phoebe suggested this job to him"], answer:1, note:"Holden feels a strong need to protect children, including Phoebe and the memory of Allie, from the pain he sees in the adult world."},
    writing:[{task:"Describe the conversation between Holden and Phoebe about what he likes.",target:"30-50 words",tips:["Say what Phoebe asks him","Say what Holden struggles to answer","Say what he finally says he wants to be"],starters:["Phoebe asked Holden...","At first, he could not...","Finally, he said he wanted to be...","He explained that..."]},{task:"Imagine you are Mr. Antolini, talking to Holden that night.",target:"30-50 words",tips:["Say what you warn him about","Say why you are worried","Say how the evening ends"],starters:["I told Holden that he was...","I was worried because...","Later that night, I...","In the end, Holden..."]}]},
  { n:8, title:"The carousel", unit:8, span:"Chapters 24–26",
    sum:"Holden sleeps in Grand Central Station, feels ill, and plans to hitchhike west and live as a deaf-mute. He leaves a note at Phoebe's school, where an obscenity scrawled on a wall enrages him, and waits for her at the museum; she arrives dragging a suitcase, determined to go with him. He refuses to let her come, and after an argument they walk to the zoo and the carousel, where he buys her a ride and, sitting in the rain in his hunting hat watching her reach for the gold ring, feels suddenly happy. Back in the present, he admits he misses everybody he has told about.",
    vocab:[["STATION","a building where trains stop"],["ILL","sick"],["HITCHHIKE","to travel by asking strangers for free rides"],["NOTE","a short written message"],["OBSCENITY","a rude or offensive word or phrase"],["ENRAGED","made someone extremely angry"],["SUITCASE","a bag used for carrying clothes when traveling"],["DETERMINED","having made a firm decision to do something"],["ARGUMENT","a disagreement, often with raised voices"],["CAROUSEL","a large, round machine at a fair with model horses that turns to music"],["RING","a small circular object; here, a gold ring riders try to catch"],["MISSED","felt sad about not seeing someone"]],
    comp:[["Where does Holden sleep that night?",["At the Edmont Hotel","In Grand Central Station","At Phoebe's school","At Mr. Antolini's apartment"],1,"He sleeps in Grand Central Station."],["What strange plan does Holden consider?",["Becoming a teacher","Hitchhiking west and living as a deaf-mute","Returning to Pencey","Moving to Vermont with Sally"],1,"He plans to hitchhike west and live as a deaf-mute."],["What does Holden see on the stairs at Phoebe's school?",["A broken window","An obscenity written on the wall","A fire","A lost suitcase"],1,"He sees an obscenity on the wall."],["Why does the obscenity upset Holden so much?",["He wrote it himself","He does not want young children to see it","It insults him personally","It is about Phoebe"],1,"He does not want young children to see it."],["What does Phoebe bring when she meets Holden?",["A record","A suitcase","Money","His hunting hat"],1,"She brings a suitcase."],["Does Holden let Phoebe come with him?",["Yes, immediately","No, he refuses","He asks their parents first","He is unsure"],1,"No, he refuses at first."],["Where do Holden and Phoebe end up together?",["At the museum","At the zoo and the carousel","At Ernie's","At the Edmont Hotel"],1,"They end up at the zoo and the carousel."],["How does Holden feel watching Phoebe on the carousel?",["Angry","Suddenly happy","Bored","Frightened"],1,"He feels suddenly happy."]],
    tf:[["Holden sleeps in Grand Central Station.",true,"This is correct."],["Holden plans to become a deaf-mute out west.",true,"This is correct."],["Phoebe brings a suitcase because she wants to go with Holden.",true,"This is correct."],["Holden happily agrees to let Phoebe come with him.",false,"He refuses at first."],["Holden and Phoebe end up at the carousel.",true,"This is correct."],["Holden feels nothing while watching Phoebe on the carousel.",false,"He feels suddenly happy."]],
    rw:[["Holden slept in Grand Central Station.",0,"Right — this is correct."],["Holden felt completely well and rested that night.",1,"Wrong — he felt ill."],["An obscenity on the wall enraged Holden.",0,"Right — this is correct."],["Phoebe arrived without any suitcase.",1,"Wrong — she pulled a heavy suitcase."],["Holden let Phoebe come with him at once.",1,"Wrong — he refused at first."],["It rained while Phoebe rode the carousel.",0,"Right — this is correct."],["Holden's parents watched Phoebe ride the carousel too.",2,"Doesn't say — the text does not mention this."]],
    halves:[["Holden sleeps","in Grand Central Station."],["He plans to hitchhike west","and live as a deaf-mute."],["An obscenity on the wall","enrages Holden deeply."],["Phoebe arrives with a suitcase,","determined to go with him."],["Holden and Phoebe argue,","and then walk to the zoo."],["Holden watches Phoebe","ride the carousel in the rain."],["He admits, at the end,","that he misses almost everybody."]],
    odd:[[["station","school","museum","obscenity"],3,"An obscenity is a word, not a place."],[["suitcase","bag","luggage","carousel"],3,"A carousel is a ride, not something for carrying clothes."],[["enraged","furious","angry","calm"],3,"Calm means the opposite of the others."],[["determined","firm","decided","unsure"],3,"Unsure means the opposite of the others."],[["argument","disagreement","fight","agreement"],3,"Agreement means the opposite of the others."]],
    gaps:{title:"Adjectives", bank:["ill","determined","upset","happy","heavy","angry"], items:[["Holden felt ___ and tired that night.","ill"],["Phoebe was ___ to go with him.","determined"],["Phoebe became ___ after the argument.","upset"],["Holden felt suddenly ___ in the rain.","happy"],["Phoebe's suitcase was ___ to carry.","heavy"],["The obscenity on the wall made Holden ___.","angry"]]},
    think:{quote:"Sitting in the rain on an old park bench, wearing his hunting hat, Holden watches his little sister go around and around on the carousel, reaching for the gold ring, and feels, just for a moment, completely happy.", question:"Why do you think Holden feels suddenly happy at this particular moment?", options:["Because the rain has stopped","Because seeing Phoebe innocent and joyful comforts him deeply","Because he has decided to go back to Pencey"], answer:1, note:"After so much sadness and loss, watching Phoebe enjoy something simple and childlike gives Holden a rare, real moment of peace."},
    writing:[{task:"Describe what happened when Phoebe arrived with her suitcase.",target:"30-50 words",tips:["Say what she wanted to do","Say how Holden reacted","Say how the argument ended"],starters:["Phoebe arrived carrying...","She wanted to...","Holden told her that...","In the end, they..."]},{task:"Imagine you are Holden, watching Phoebe on the carousel in the rain.",target:"30-50 words",tips:["Say what the weather was like","Say what Phoebe was doing","Say how you felt"],starters:["It was raining, but I...","Phoebe went around and around, reaching for...","Watching her, I felt...","At that moment, I..."]}]}
